// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

let centroids = [], centroidsIdx = 0;
let nFlowers = 18, nPetals = 12;
let margin = 100;
let petalEnds = [];

function setup() {
	createCanvas(500, 500);
	pixelDensity(2);
	background("#fffbe6");
	noStroke();

	for (let i = 0; i < nFlowers; i++) {
		let x0 = random(margin, width-margin);
		let y0 = random(margin, height-margin);
		centroids.push({x0: x0, y0: y0, theta0: random(TAU), id: i, arcsLeft: shuffle([...Array(nPetals).keys()])});
	}
	for (let i = 0; i < 3; i++) voronoiRelaxation();
}

function draw() {
	let c = centroids[centroidsIdx];
	let theta = TAU*c.arcsLeft.pop()/nPetals + c.theta0;
	let rMax = longestPossibleRadius(c, theta);

	fill(5);
	let x, y, d = 0, r = 0;
	while (r+d/2 < rMax) {
		x = c.x0 + r*cos(theta);
		y = c.y0 + r*sin(theta);
		d = r*sin(TAU/nPetals);
		circle(x, y, d+1);

		if (x < margin/2 || x > width-margin/2 || y < margin/2 || y > height-margin/2) break;
		let intersects = false;
		for (let p of petalEnds) {
			if (p.id != c.id && dist(x, y, p.x, p.y) < d/2 + p.d/2 + 6) {
				intersects = true;
				break;
			}
		}
		if (intersects) break;

		r++;
	}
	petalEnds.push({x: x, y: y, d: d, id: c.id});

	r = 0;
	let borderThickness = 3;
	fill("#fffbe6");
	while (r*sin(TAU/nPetals) <= d) {
		x = c.x0 + r*cos(theta);
		y = c.y0 + r*sin(theta);
		circle(x, y, r*sin(TAU/nPetals)+1-borderThickness);
		r += 1/4;
	}

	if (c.arcsLeft.length == 0) {
		let dSum = 0;
		for (let p of petalEnds) {
			if (p.id == c.id) {
				dSum += p.d;
			}
		}
		fill(5);
		circle(c.x0, c.y0, dSum/nPetals);
		fill("#f9d531");
		circle(c.x0, c.y0, dSum/nPetals-borderThickness);
		centroidsIdx++;
	}
	if (centroidsIdx >= centroids.length) noLoop();
}

function voronoiRelaxation() {
	let n = 20, s = width/n;
	let voronoi = Array(nFlowers).fill().map(()=>[]);
	for (let i = 0; i < n; i++) {
		let x = (i+1/2)*s;
		for (let j = 0; j < n; j++) {
			let y = (j+1/2)*s;
			let cid = closestCentroidId(x, y);
			voronoi[cid].push([x, y]);
		}
	}

	for (let i = 0; i < nFlowers; i++) {
		let c = centroids[i];
		let cellPoints = voronoi[c.id];
		let xSum = 0, ySum = 0;
		for (let p of cellPoints) {
			xSum += p[0];
			ySum += p[1];
		}
		let x1 = constrain(xSum/cellPoints.length, margin, width-margin);
		let y1 = constrain(ySum/cellPoints.length, margin, height-margin);
		c.x0 = x1;
		c.y0 = y1;
	}
}

function longestPossibleRadius(centroid, theta) {
	let x0 = centroid.x0, y0 = centroid.y0;
	let r = 0;
	let rMax = min(min(x0, width-x0), min(y0, height-y0));
	let rStep = 2;
	while (true) {
		r += rStep;
		let x = x0 + r*cos(theta), y = y0 + r*sin(theta);
		if (closestCentroidId(x, y) != centroid.id) {
			break;
		}
		if (x < 0 || x > width || y < 0 || y > height) {
			break;
		}
	}
	return r-rStep;
}

function closestCentroidId(x, y) {
	let minDist = Infinity, idMin = -1;
	for (let c of centroids) {
		let d = distToCentroidSquared(c, x, y);
		if (d < minDist) {
			minDist = d;
			idMin = c.id;
		}
	}
	return idMin;
}

function distToCentroidSquared(c, x, y) {
	return sq(c.x0 - x) + sq(c.y0 - y);
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
